func TestShadowStrategy_CommitStoresGitNativeLinkage(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)

	session := env.NewSession()
	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}

	env.WriteFile("feature.txt", "feature from Claude")
	session.CreateTranscript("Create feature file", []FileChange{
		{Path: "feature.txt", Content: "feature from Claude"},
	})

	if err := env.SimulateStop(session.ID, session.TranscriptPath); err != nil {
		t.Fatalf("SimulateStop failed: %v", err)
	}

	env.GitCommitWithShadowHooks("Add feature file", "feature.txt")

	commitHash := env.GetHeadHash()
	checkpointID := env.GetCheckpointIDFromCommitMessage(commitHash)
	if checkpointID == "" {
		t.Fatal("expected commit to have Entire-Checkpoint trailer")
	}

	repo, err := git.PlainOpen(env.RepoDir)
	if err != nil {
		t.Fatalf("failed to open repo: %v", err)
	}

	store := checkpoint.NewGitStore(repo)
	summary, err := store.ReadCommitted(context.Background(), id.MustCheckpointID(checkpointID))
	if err != nil {
		t.Fatalf("ReadCommitted failed: %v", err)
	}
	if summary == nil {
		t.Fatal("expected committed checkpoint summary")
	}
	if summary.Linkage == nil {
		t.Fatal("expected linkage metadata")
	}
	if summary.Linkage.TreeHash == "" {
		t.Fatal("expected tree_hash to be populated")
	}
	if summary.Linkage.PatchID == "" {
		t.Fatal("expected patch_id to be populated")
	}
	if len(summary.Linkage.TreeHash) != 40 {
		t.Fatalf("tree_hash length = %d, want 40", len(summary.Linkage.TreeHash))
	}
	if len(summary.Linkage.PatchID) != 40 {
		t.Fatalf("patch_id length = %d, want 40", len(summary.Linkage.PatchID))
	}
}
